import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long x = scanner.nextLong();
        long y = scanner.nextLong();
        long n = scanner.nextLong();

        double closestDiff = 1e15;
        long finalNum = 0;
        long finalDen = 1;

        for (long b = 1; b <= n; b++) {
            long a = (x * b) / y;

            // Lambda equivalent as a method
            class Checker {
                void checkAndUpdate(long candidate) {
                    double diff = Math.abs(x * b - candidate * y) / (double)(y * b);
                    if (diff < closestDiff) {
                        closestDiff = diff;
                        finalNum = candidate;
                        finalDen = b;
                    }
                }
            }
            Checker checker = new Checker();

            if (a > 0 && (x * b - (a - 1) * y) == 0) {
                System.out.println((a - 1) + "/" + b);
                return;
            }
            if ((x * b - a * y) == 0) {
                System.out.println(a + "/" + b);
                return;
            }
            if ((x * b - (a + 1) * y) == 0) {
                System.out.println((a + 1) + "/" + b);
                return;
            }

            checker.checkAndUpdate(a - 1);
            checker.checkAndUpdate(a);
            checker.checkAndUpdate(a + 1);
        }
        System.out.println(finalNum + "/" + finalDen);
    }
}
